function go(q) {
  if (q && q.trim())
    location.href =
      "https://findspreadsheet.com/search.html?channelid=2&keywords=" +
      encodeURIComponent(q.trim());
}
const pageLocale = { nodes: [], attrs: [], dictionary: null, dictionaryPromise: null };
const chromeCopy = {
  en: ["Home","Product categories","Product details","SEO articles","FAQ","QC & tracking"],
  de: ["Startseite","Produktkategorien","Produktdetails","SEO-Artikel","FAQ","QC & Sendungsverfolgung"],
  fr: ["Accueil","Catégories de produits","Détails produit","Articles SEO","FAQ","QC et suivi"],
  es: ["Inicio","Categorías de productos","Detalles del producto","Artículos SEO","FAQ","QC y seguimiento"],
  it: ["Home","Categorie prodotto","Dettagli prodotto","Articoli SEO","FAQ","QC e tracciamento"],
  pt: ["Início","Categorias de produtos","Detalhes do produto","Artigos SEO","FAQ","QC e rastreio"],
  nl: ["Start","Productcategorieën","Productdetails","SEO-artikelen","FAQ","QC en tracking"],
  pl: ["Strona główna","Kategorie produktów","Szczegóły produktu","Artykuły SEO","FAQ","QC i śledzenie"],
  sv: ["Hem","Produktkategorier","Produktdetaljer","SEO-artiklar","FAQ","QC och spårning"],
};
function updateNavigation(lang) {
  (chromeCopy[lang] || chromeCopy.en).forEach((label, index) => {
    const link = document.querySelectorAll(".navlinks a")[index];
    if (link) link.textContent = label;
  });
}
function applyHomepageCopy(lang) {
  const locale = copy[lang] || copy.en;
  const instantKeys = new Set(["title", "lead", "search", "db"]);
  document.querySelectorAll("[data-t]").forEach((element) => {
    const key = element.dataset.t;
    const value = instantKeys.has(key) ? locale[key] : null;
    if (value) element.textContent = value;
  });
  document.querySelectorAll("[data-ph]").forEach((element) => {
    const value = locale[element.dataset.ph];
    if (value) element.placeholder = value;
  });
}
function currentLanguage() {
  return (new URLSearchParams(location.search).get("lang") || localStorage.getItem("lb-lang") || "en").toLowerCase();
}
function rememberEnglishPage() {
  if (pageLocale.nodes.length) return;
  for (const root of document.querySelectorAll(".hero, main, footer")) {
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
      acceptNode: (node) => node.parentElement && ["SCRIPT", "STYLE"].includes(node.parentElement.tagName)
        ? NodeFilter.FILTER_REJECT
        : node.nodeValue.trim() ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT,
    });
    let node;
    while ((node = walker.nextNode())) pageLocale.nodes.push({ node, source: node.nodeValue });
    root.querySelectorAll("[placeholder], input[type='submit'][value]").forEach((element) => {
      if (element.placeholder && element.placeholder.trim()) pageLocale.attrs.push({ element, property: "placeholder", source: element.placeholder });
      if (element.matches("input[type='submit']") && element.value && element.value.trim()) pageLocale.attrs.push({ element, property: "value", source: element.value });
    });
  }
}
function sourceParts(source) {
  const leading = source.match(/^\s*/)[0];
  const trailing = source.match(/\s*$/)[0];
  return [leading, source.trim(), trailing];
}
async function loadDictionary() {
  if (pageLocale.dictionary) return pageLocale.dictionary;
  if (!pageLocale.dictionaryPromise) {
    pageLocale.dictionaryPromise = fetch("/assets/i18n.json", { cache: "force-cache" })
      .then((response) => {
        if (!response.ok) throw new Error("Locale dictionary unavailable");
        return response.json();
      })
      .then((dictionary) => (pageLocale.dictionary = dictionary));
  }
  return pageLocale.dictionaryPromise;
}
async function applyLanguage(lang) {
  const dictionary = lang === "en" ? null : await loadDictionary();
  const translations = dictionary?.[lang] || {};
  document.documentElement.lang = lang;
  updateNavigation(lang);
  pageLocale.nodes.forEach(({ node, source }) => {
    const [leading, text, trailing] = sourceParts(source);
    node.nodeValue = leading + (translations[text] || text) + trailing;
  });
  pageLocale.attrs.forEach(({ element, property, source }) => {
    const [, text] = sourceParts(source);
    element[property] = translations[text] || text;
  });
  applyHomepageCopy(lang);
}
function init() {
  const lang = (
    new URLSearchParams(location.search).get("lang") ||
    localStorage.getItem("lb-lang") ||
    "en"
  ).toLowerCase();
  document.documentElement.lang = lang;
  updateNavigation(lang);
  rememberEnglishPage();
  applyHomepageCopy(lang);
  let select = document.querySelector("#language");
  if (!select) {
    select = document.createElement("select");
    select.id = "language";
    select.className = "language";
    select.setAttribute("aria-label", "Language");
    select.innerHTML = '<option value="en">EN</option><option value="de">DE</option><option value="fr">FR</option><option value="es">ES</option><option value="it">IT</option><option value="pt">PT</option><option value="nl">NL</option><option value="pl">PL</option><option value="sv">SV</option>';
    document.querySelector(".nav")?.append(select);
  }
  if (select) {
    select.value = lang;
    select.addEventListener("change", async (e) => {
      const next = e.target.value;
      select.disabled = true;
      try {
        await applyLanguage(next);
        localStorage.setItem("lb-lang", next);
        const u = new URL(location.href);
        u.searchParams.set("lang", next);
        history.replaceState({}, "", u);
      } finally {
        select.disabled = false;
      }
    });
  }
  document
    .querySelectorAll("[data-query]")
    .forEach((b) => b.addEventListener("click", () => go(b.dataset.query)));
  document.querySelectorAll("form[data-search]").forEach((f) =>
    f.addEventListener("submit", (e) => {
      e.preventDefault();
      go(f.querySelector("input").value);
    }),
  );
  loadDictionary().catch(() => {});
  applyLanguage(lang).catch(() => {});
}
document.addEventListener("DOMContentLoaded", init);
